def _double_with_z_1(X1, Y1, p, a):
    """Add a point to itself with z == 1."""
    # after:
    # http://hyperelliptic.org/EFD/g1p/auto-shortw-jacobian.html#doubling-mdbl-2007-bl
    XX, YY = X1 * X1 % p, Y1 * Y1 % p
    if not YY:
        return 0, 0, 0
    YYYY = YY * YY % p
    S = 2 * ((X1 + YY) ** 2 - XX - YYYY) % p
    M = 3 * XX + a
    T = (M * M - 2 * S) % p
    # X3 = T
    Y3 = (M * (S - T) - 8 * YYYY) % p
    Z3 = 2 * Y1 % p
    return T, Y3, Z3


